/**
 * Bad News
 * ----------
 * Hanani comes from Judah and tells Nehemiah that the wall of Jerusalem is broken and its people are in trouble. Stage: a palace court at Susa in winter, a cupbearer hearing a report, a map of a ruined city; a man turning to prayer, his face in the light.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dawn · hero: city
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./nehemiah-kit.js.
 */

import { THREE, createScene, column, throne, cityGate, person, crowd, birds } from './nehemiah-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 4004915677, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x142014 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x111b11 });

    /* hero: the city gate */
    cityGate(W, group, 0, 0, -8, 1.1, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x1e301e, wrapTrim: 0x121d12, beard: 'long', staff: 'planted', bend: 0.12, armR: [2.5, 0.35], armL: [0.3, 0.1], ry: 0.23, s: 1.04 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 23, 70, 44, [0x1a2a1a, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    /* birds: slow circles high above */
    birds(W, group, 8, 55, { y: 26 });

    return W.finish();
}

export default { build };
